class Solution {
public:
    int maxLength(vector<string>& arr) {
        int n = arr.size();
        vector<int> masks(n, 0);
        vector<int> valid(n, 0);
        for (int i = 0; i < n; i++) {
            int m = 0;
            bool ok = true;
            for (char c : arr[i]) {
                int bit = 1 << (c - 'a');
                if (m & bit) { ok = false; break; }
                m |= bit;
            }
            masks[i] = m;
            valid[i] = ok ? (int)arr[i].size() : -1;
        }
        int best = 0;
        dfs(0, 0, 0, masks, valid, n, best);
        return best;
    }
private:
    void dfs(int idx, int usedMask, int len, vector<int>& masks, vector<int>& valid, int n, int& best) {
        if (idx == n) {
            best = max(best, len);
            return;
        }
        dfs(idx + 1, usedMask, len, masks, valid, n, best);
        if (valid[idx] >= 0 && (usedMask & masks[idx]) == 0) {
            dfs(idx + 1, usedMask | masks[idx], len + valid[idx], masks, valid, n, best);
        }
    }
};
